def bubble_sort(nums):
    arr = list(nums)
    n = len(arr)
    for i in range(n):
        swapped = False
        for j in range(n - 1 - i):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                swapped = True
        if not swapped:
            break
    return arr

import queue
import threading


class Future:
    def __init__(self):
        self._event = threading.Event()
        self._result = None
        self._error = None

    def set_result(self, value):
        self._result = value
        self._event.set()

    def set_error(self, exc):
        self._error = exc
        self._event.set()

    def result(self, timeout=None):
        if not self._event.wait(timeout):
            raise TimeoutError("future not ready")
        if self._error is not None:
            raise self._error
        return self._result


class ThreadPool:
    def __init__(self, max_workers):
        self._tasks = queue.Queue()
        self._workers = [
            threading.Thread(target=self._worker, daemon=True)
            for _ in range(max_workers)
        ]
        for w in self._workers:
            w.start()

    def _worker(self):
        while True:
            fn, args, future = self._tasks.get()
            try:
                future.set_result(fn(*args))
            except Exception as e:  # noqa: BLE001
                future.set_error(e)
            finally:
                self._tasks.task_done()

    def submit(self, fn, *args):
        future = Future()
        self._tasks.put((fn, args, future))
        return future

    def shutdown(self, wait=True):
        if wait:
            self._tasks.join()

import time


class TTLKVStore:
    def __init__(self):
        self._data = {}

    def set(self, key, value, ttl=None):
        expire_at = None if ttl is None else time.monotonic() + ttl
        self._data[key] = (value, expire_at)

    def get(self, key):
        if key not in self._data:
            return None
        value, expire_at = self._data[key]
        if expire_at is not None and time.monotonic() > expire_at:
            del self._data[key]
            return None
        return value

    def delete(self, key):
        if key in self._data:
            del self._data[key]
            return True
        return False

    def __len__(self):
        now = time.monotonic()
        expired = [k for k, (_, exp) in self._data.items()
                   if exp is not None and now > exp]
        for k in expired:
            del self._data[k]
        return len(self._data)
